// Author: Shaobo He

predicate knows(a: int, b: int)

predicate isCelebrity(n : int, i : int)
requires n >= 0 && 0 <= i < n;
{
    forall j :: 0 <= j < n && i != j ==> knows(j, i) && !knows(i, j)
}

lemma knowerCannotBeCelebrity(n: int, i: int)
requires n >= 0 && 0 <= i < n
ensures (exists j :: 0 <= j < n && j != i && knows(i, j)) ==> !isCelebrity(n, i)
{
    if exists j :: 0 <= j < n && j != i && knows(i, j) {
        var j :| 0 <= j < n && j != i && knows(i, j);
        assert !isCelebrity(n, i);
    }
}

lemma unknownByCannotBeCelebrity(n: int, i: int)
requires n >= 0 && 0 <= i < n
ensures (exists j :: 0 <= j < n && j != i && !knows(j, i)) ==> !isCelebrity(n, i)
{
    if exists j :: 0 <= j < n && j != i && !knows(j, i) {
        var j :| 0 <= j < n && j != i && !knows(j, i);
        assert !isCelebrity(n, i);
    }
}

ghost method isCelebrityP(n: int, i: int) returns (r : bool)
requires n >= 0 && 0 <= i < n;
