{
    var j := 0;
    r := true;
    while j < n
    decreases n - j;
    invariant 0 <= j <= n;
    invariant r ==> forall k :: 0 <= k < j && k != i ==> knows(k, i) && !knows(i, k);
    {
        if j != i {
            if !knows(j, i) || knows(i, j) {
                return false;
            }
        }
        j := j + 1;
    }
    return r;
} 

ghost method findCelebrity(n : int) returns (r : int)
requires 2 <= n <= 100;
ensures 0 <= r < n ==> isCelebrity(n, r);
ensures r == -1 ==> forall i :: 0 <= i < n ==> !isCelebrity(n, i);
{
    var candidate := 0;
    var i := 1;
    while i < n 
    invariant 1 <= i <= n;
    invariant 0 <= candidate < i;
    invariant forall j :: 0 <= j < i && j != candidate ==> !isCelebrity(n, j);
    {
        if knows(candidate, i) {
            assert exists j :: 0 <= j < n && j != candidate && knows(candidate, j);
            knowerCannotBeCelebrity(n, candidate);
            assert !isCelebrity(n, candidate);
            candidate := i;
        } else {
            assert exists j :: 0 <= j < n && j != i && !knows(j, i);
            unknownByCannotBeCelebrity(n, i);
